final def create(initialMaxOps: Int): Array[Int] =
  new Array[Int](1 + 1 + ((initialMaxOps - 1) >> 3)) // count-slot + 1 for each set of 8 ops

final def growIfNeeded(stack: Array[Int], count: Int): Array[Int] = {
  if ((1 + ((count + 1) >> 3)) < stack.length) {
    stack
  } else {
    Arrays.copyOf(stack, 2 * stack.length) // Count in stack(0) copied "for free"
  }
}

final def push(stack: Array[Int], op: Byte): Array[Int] = {
  val c = stack(0) // current count of elements
  val use = growIfNeeded(stack, c) // alias so we add to the right place
  val s = (c >> 3) + 1 // current slot in `use`
  val shift = (c & 7) << 2 // BEGIN MAGIC
  use(s) = (use(s) & ~(0xffffffff << shift)) | (op << shift) // END MAGIC
  use(0) += 1 // write the new count

"Batch draining" should {
  "work correctly in the presence of concurrent stealers" in real {
    val iterations = 500000

    def catsEffectRepeat[A](n: Int)(io: IO[A]): IO[A] =
      if (n <= 1) io
      else io.flatMap(_ => catsEffectRepeat(n - 1)(io))

    def iterate(deferred: Deferred[IO, Unit], n: Int): IO[Any] =
      for {
        ref <- IO.ref(n)
        queue <- Queue.bounded[IO, Unit](1)
        effect = queue.offer(()).start >>
          queue.take >>
          ref.modify(n => (n - 1, if (n == 1) deferred.complete(()) else IO.unit)).flatten
        _ <- catsEffectRepeat(iterations)(effect.start)
      } yield ()

    for {
      deferred <- IO.deferred[Unit]
      _ <- iterate(deferred, iterations).start
      _ <- deferred.get
      res <- IO(ok)
    } yield res
